{"version":3,"file":"dark-store-app.jsdbx","sources":["../../src/client/dark-store-app.css","../../src/client/dark-store-app.tsx"],"sourcesContent":["/* --- Dark Store Dashboard — Dark Theme --- */

/* --- Dashboard Shell --- */
.ds-dashboard {
  min-height: 100vh;
  background: #0a0e14;
  color: #e2e8f0;
  font-family: -apple-system, BlinkMacSystemFont, 'Inter', 'Segoe UI', sans-serif;
}

.ds-dashboard__content {
  padding: 24px;
  max-width: 1440px;
  margin: 0 auto;
}

/* --- Breadcrumb --- */
.ds-breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 16px;
  font-size: 13px;
}

.ds-breadcrumb__link {
  color: #3b82f6;
  text-decoration: none;
}

.ds-breadcrumb__link:hover {
  text-decoration: underline;
}

.ds-breadcrumb__sep {
  color: #475569;
}

.ds-breadcrumb__current {
  color: #94a3b8;
}

/* --- Store Header Card --- */
.ds-store-header {
  background: #111621;
  border: 1px solid #1a2035;
  border-radius: 12px;
  padding: 24px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 16px;
}

.ds-store-header__left {
  flex: 1;
}

.ds-store-header__title-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 6px;
}

.ds-store-header__name {
  font-size: 24px;
  font-weight: 700;
  color: #e2e8f0;
  margin: 0;
}

.ds-store-header__id-badge {
  font-size: 12px;
  font-weight: 600;
  color: #64748b;
  background: rgba(100, 116, 139, 0.12);
  border: 1px solid #1a2035;
  border-radius: 6px;
  padding: 3px 10px;
}

.ds-store-header__subtitle {
  font-size: 13px;
  color: #64748b;
  margin: 0 0 12px 0;
}

.ds-store-header__pills {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.ds-store-header__pill {
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 6px;
}

.ds-store-header__pill--red {
  color: #ef4444;
  background: rgba(239, 68, 68, 0.08);
  border: 1px solid rgba(239, 68, 68, 0.2);
}

.ds-store-header__pill--grey {
  color: #94a3b8;
  background: rgba(148, 163, 184, 0.08);
  border: 1px solid rgba(148, 163, 184, 0.15);
}

.ds-store-header__right {
  flex-shrink: 0;
}

.ds-store-header__live-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: #94a3b8;
  background: rgba(34, 197, 94, 0.06);
  border: 1px solid rgba(34, 197, 94, 0.2);
  border-radius: 20px;
  padding: 5px 14px;
}

.ds-store-header__live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #22c55e;
  animation: ds-pulse-glow 2s infinite;
}

@keyframes ds-pulse-glow {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

/* --- PulseScore Breakdown --- */
.ds-pulse-breakdown {
  background: #111621;
  border: 1px solid #1a2035;
  border-radius: 12px;
  padding: 24px;
  margin-bottom: 16px;
}

.ds-pulse-breakdown__text {
  margin-bottom: 14px;
}

.ds-pulse-breakdown__formula {
  font-size: 14px;
  color: #94a3b8;
}

.ds-pulse-breakdown__score {
  font-size: 28px;
  font-weight: 700;
  color: #ef4444;
  font-variant-numeric: tabular-nums;
}

.ds-pulse-breakdown__bar {
  display: flex;
  height: 24px;
  border-radius: 6px;
  overflow: hidden;
  gap: 2px;
  margin-bottom: 10px;
}

.ds-pulse-breakdown__segment {
  border-radius: 4px;
}

.ds-pulse-breakdown__segment--green {
  background: #22c55e;
}

.ds-pulse-breakdown__segment--red {
  background: #ef4444;
}

.ds-pulse-breakdown__labels {
  display: flex;
  gap: 24px;
  margin-bottom: 12px;
}

.ds-pulse-breakdown__label {
  font-size: 11px;
  font-weight: 600;
  color: #ef4444;
}

.ds-pulse-breakdown__caption {
  font-size: 12px;
  color: #64748b;
  font-style: italic;
  margin: 0;
  line-height: 1.5;
}

/* --- KPI Row --- */
.ds-kpi-row {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
  margin-bottom: 24px;
}

/* --- KPI Card --- */
.ds-kpi-card {
  background: #111621;
  border: 1px solid #1a2035;
  border-radius: 12px;
  padding: 20px;
  display: flex;
  flex-direction: column;
}

.ds-kpi-card__label {
  font-size: 11px;
  font-weight: 600;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  margin-bottom: 10px;
}

.ds-kpi-card__value-row {
  display: flex;
  align-items: baseline;
  gap: 4px;
  margin-bottom: 10px;
}

.ds-kpi-card__value {
  font-size: 28px;
  font-weight: 700;
  color: #e2e8f0;
  font-variant-numeric: tabular-nums;
}

.ds-kpi-card__suffix {
  font-size: 14px;
  color: #64748b;
}

.ds-kpi-card__caption {
  font-size: 11px;
  color: #64748b;
  margin: 0;
  line-height: 1.5;
}

.ds-kpi-card__subcaption {
  font-size: 11px;
  color: #475569;
  margin: 4px 0 0 0;
  line-height: 1.5;
}

/* --- Generic Card --- */
.ds-card {
  background: #111621;
  border: 1px solid #1a2035;
  border-radius: 12px;
  padding: 24px;
}

.ds-card__header {
  margin-bottom: 16px;
}

.ds-card__title {
  font-size: 15px;
  font-weight: 600;
  color: #e2e8f0;
  margin: 0 0 4px 0;
}

.ds-card__subtitle {
  font-size: 12px;
  color: #64748b;
  margin: 0;
}

/* --- Two-Column Layout --- */
.ds-dashboard__two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 24px;
}

/* --- Three-Column Layout --- */
.ds-dashboard__three-col {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 16px;
  margin-bottom: 24px;
}

.ds-dashboard__complaints-col {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* --- Bar Chart (Equipment) --- */
.ds-bar-chart {
  display: flex;
  gap: 8px;
  height: 180px;
  margin-bottom: 12px;
}

.ds-bar-chart__y-axis {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 0 4px 24px 0;
}

.ds-bar-chart__y-label {
  font-size: 10px;
  color: #475569;
  text-align: right;
  width: 20px;
}

.ds-bar-chart__body {
  display: flex;
  flex: 1;
  align-items: flex-end;
  gap: 4px;
  padding-bottom: 24px;
  border-bottom: 1px solid #1a2035;
}

.ds-bar-chart__col {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100%;
}

.ds-bar-chart__bar-group {
  flex: 1;
  width: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 2px;
}

.ds-bar-chart__bar {
  width: 40%;
  border-radius: 2px 2px 0 0;
  min-height: 2px;
}

.ds-bar-chart__bar--red {
  background: #ef4444;
}

.ds-bar-chart__bar--amber {
  background: #f59e0b;
}

.ds-bar-chart__x-label {
  font-size: 8px;
  color: #475569;
  margin-top: 6px;
  text-align: center;
  white-space: nowrap;
}

/* --- Chart Legend --- */
.ds-chart__legend {
  display: flex;
  gap: 20px;
  margin-top: 12px;
}

.ds-chart__legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: #64748b;
}

.ds-chart__legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.ds-chart__legend-dot--red {
  background: #ef4444;
}

.ds-chart__legend-dot--amber {
  background: #f59e0b;
}

.ds-chart__legend-dot--blue {
  background: #3b82f6;
}

/* --- Line Chart (SVG) --- */
.ds-line-chart-wrap {
  position: relative;
  margin-bottom: 8px;
}

.ds-line-chart-svg {
  display: block;
  width: 100%;
}

.ds-chart__axis-text {
  font-size: 10px;
  fill: #475569;
}

/* --- Tooltip --- */
.ds-tooltip {
  position: absolute;
  transform: translate(-50%, -100%);
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 6px;
  padding: 8px 12px;
  pointer-events: none;
  z-index: 10;
}

.ds-tooltip__date {
  font-size: 11px;
  font-weight: 600;
  color: #e2e8f0;
  margin-bottom: 4px;
}

.ds-tooltip__row {
  font-size: 11px;
  color: #94a3b8;
  line-height: 1.5;
}

/* --- List (Work Orders, Repairs, Complaints) --- */
.ds-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ds-list__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  border-radius: 8px;
  transition: background 0.12s ease;
}

.ds-list__row--clickable {
  cursor: pointer;
}

.ds-list__row--clickable:hover {
  background: rgba(255, 255, 255, 0.03);
}

.ds-list__row-main {
  flex: 1;
  min-width: 0;
}

.ds-list__row-top {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 3px;
}

.ds-list__row-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.ds-list__row-id {
  font-size: 12px;
  font-weight: 600;
  color: #e2e8f0;
  font-family: 'SF Mono', 'Fira Code', monospace;
}

.ds-list__badge {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 4px;
  border: 1px solid;
  background: transparent;
}

.ds-list__status {
  font-size: 11px;
  color: #94a3b8;
}

.ds-list__row-detail {
  font-size: 11px;
  color: #64748b;
}

.ds-list__row-sla {
  font-size: 10px;
  color: #475569;
  white-space: nowrap;
}

.ds-list__pill {
  font-size: 11px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 6px;
  border: 1px solid;
  background: transparent;
  white-space: nowrap;
  flex-shrink: 0;
}

/* --- Categories --- */
.ds-categories {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.ds-categories__row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.ds-categories__name {
  font-size: 12px;
  color: #94a3b8;
  width: 140px;
  flex-shrink: 0;
}

.ds-categories__bar-wrap {
  flex: 1;
  height: 8px;
  background: #1a2035;
  border-radius: 4px;
  overflow: hidden;
}

.ds-categories__bar {
  height: 100%;
  background: #3b82f6;
  border-radius: 4px;
}

.ds-categories__count {
  font-size: 12px;
  font-weight: 600;
  color: #e2e8f0;
  width: 28px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

/* --- Responsive --- */
@media (max-width: 1200px) {
  .ds-kpi-row {
    grid-template-columns: repeat(3, 1fr);
  }
  .ds-dashboard__two-col {
    grid-template-columns: 1fr;
  }
  .ds-dashboard__three-col {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .ds-kpi-row {
    grid-template-columns: repeat(2, 1fr);
  }
  .ds-store-header {
    flex-direction: column;
    gap: 12px;
  }
}
","import React, { useState, useEffect } from 'react';
import NavHeader from './components/shared/NavHeader';
import './dark-store-app.css';

/*
 * Dark Store Dashboard — DarkOps
 * Store-level view showing PulseScore breakdown, KPIs, charts, and detail cards.
 * All data is hardcoded to match spec for DS-1462 (Kolkata Central DS).
 */

const storeId = new URLSearchParams(window.location.search).get('store') || 'DS-1462';

/* --- Breadcrumb --- */
function Breadcrumb() {
  return (
    <div className="ds-breadcrumb">
      <a href="/x_2145749_qc_exec_dashboard.do" className="ds-breadcrumb__link">Executive</a>
      <span className="ds-breadcrumb__sep">&gt;</span>
      <span className="ds-breadcrumb__current">Kolkata / {storeId}</span>
    </div>
  );
}

/* --- Store Header Card --- */
function StoreHeader() {
  const [seconds, setSeconds] = useState(15);

  useEffect(() => {
    const interval = setInterval(() => {
      setSeconds((s) => s + 1);
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="ds-store-header">
      <div className="ds-store-header__left">
        <div className="ds-store-header__title-row">
          <h1 className="ds-store-header__name">Kolkata Central DS</h1>
          <span className="ds-store-header__id-badge">{storeId}</span>
        </div>
        <p className="ds-store-header__subtitle">
          Kolkata · Manager: S. Deshpande · 14 pickers on shift · 6 riders assigned
        </p>
        <div className="ds-store-header__pills">
          <span className="ds-store-header__pill ds-store-header__pill--red">SLA 61.9%</span>
          <span className="ds-store-header__pill ds-store-header__pill--red">Refunds 10%</span>
          <span className="ds-store-header__pill ds-store-header__pill--grey">Avg resolution 129m</span>
        </div>
      </div>
      <div className="ds-store-header__right">
        <span className="ds-store-header__live-pill">
          <span className="ds-store-header__live-dot" />
          Updated {seconds}s ago · LIVE
        </span>
      </div>
    </div>
  );
}

/* --- PulseScore Breakdown --- */
function PulseScoreBreakdown() {
  const deductions = [
    { label: 'Equipment', value: 18 },
    { label: 'SLA', value: 23 },
    { label: 'Refunds', value: 11 },
    { label: 'Delays', value: 17 },
  ];
  const totalDeducted = deductions.reduce((sum, d) => sum + d.value, 0);
  const remaining = 100 - totalDeducted;

  return (
    <div className="ds-pulse-breakdown">
      <div className="ds-pulse-breakdown__text">
        <span className="ds-pulse-breakdown__formula">
          100 baseline -18 Equipment -23 SLA -11 Refunds -17 Delays ={' '}
          <span className="ds-pulse-breakdown__score">31</span> /100 PulseScore
        </span>
      </div>
      <div className="ds-pulse-breakdown__bar">
        <div
          className="ds-pulse-breakdown__segment ds-pulse-breakdown__segment--green"
          style={{ flex: remaining }}
        />
        {deductions.map((d) => (
          <div
            key={d.label}
            className="ds-pulse-breakdown__segment ds-pulse-breakdown__segment--red"
            style={{ flex: d.value }}
          />
        ))}
      </div>
      <div className="ds-pulse-breakdown__labels">
        {deductions.map((d) => (
          <span key={d.label} className="ds-pulse-breakdown__label">
            {d.label} -{d.value}
          </span>
        ))}
      </div>
      <p className="ds-pulse-breakdown__caption">
        PulseScore is not a black box: it starts at 100 and subtracts equipment downtime, SLA misses, refund rate and delivery/picker delays. Fix a driver and the score moves.
      </p>
    </div>
  );
}

/* --- KPI Card --- */
interface KpiCardProps {
  label: string;
  value: string;
  valueSuffix?: string;
  valueColor?: string;
  caption: string;
  subcaption?: string;
}

function KpiCard({ label, value, valueSuffix, valueColor, caption, subcaption }: KpiCardProps) {
  return (
    <div className="ds-kpi-card">
      <span className="ds-kpi-card__label">{label}</span>
      <div className="ds-kpi-card__value-row">
        <span className="ds-kpi-card__value" style={valueColor ? { color: valueColor } : undefined}>
          {value}
        </span>
        {valueSuffix && <span className="ds-kpi-card__suffix">{valueSuffix}</span>}
      </div>
      <p className="ds-kpi-card__caption">{caption}</p>
      {subcaption && <p className="ds-kpi-card__subcaption">{subcaption}</p>}
    </div>
  );
}

/* --- KPI Row --- */
function KpiRow() {
  return (
    <div className="ds-kpi-row">
      <KpiCard
        label="PULSESCORE"
        value="31"
        valueSuffix="/100"
        valueColor="#ef4444"
        caption="network avg 78"
      />
      <KpiCard
        label="EQUIPMENT FAILURES"
        value="10"
        caption="last 14d"
        subcaption="network avg 3 · 4 work orders open"
      />
      <KpiCard
        label="INVENTORY ISSUES"
        value="17"
        caption="stockouts + mismatches"
        subcaption="today · network avg 6"
      />
      <KpiCard
        label="DELIVERY DELAYS"
        value="97"
        caption="orders > 20 min"
        subcaption="today · network avg 28"
      />
      <KpiCard
        label="PICKER DELAY"
        value="5.3m"
        caption="avg per order"
        subcaption="network avg 2.1m · target 2.5m"
      />
    </div>
  );
}

/* --- Equipment Failures Bar Chart (CSS bars) --- */
function EquipmentChart() {
  const days = [
    { date: '18 Jul', failures: 3, downtime: 2 },
    { date: '19 Jul', failures: 2, downtime: 2 },
    { date: '20 Jul', failures: 4, downtime: 3 },
    { date: '21 Jul', failures: 3, downtime: 2 },
    { date: '22 Jul', failures: 5, downtime: 4 },
    { date: '23 Jul', failures: 6, downtime: 5 },
    { date: '24 Jul', failures: 4, downtime: 3 },
    { date: '25 Jul', failures: 3, downtime: 2 },
    { date: '26 Jul', failures: 5, downtime: 4 },
    { date: '27 Jul', failures: 6, downtime: 5 },
    { date: '28 Jul', failures: 4, downtime: 3 },
    { date: '29 Jul', failures: 5, downtime: 4 },
    { date: '30 Jul', failures: 6, downtime: 5 },
    { date: '31 Jul', failures: 4, downtime: 3 },
  ];
  const yMax = 8;
  const yTicks = [0, 2, 4, 6, 8];

  return (
    <div className="ds-card">
      <div className="ds-card__header">
        <h3 className="ds-card__title">Equipment failures — 14 days</h3>
        <p className="ds-card__subtitle">Failures and downtime hours; cold chain drives quality complaints.</p>
      </div>
      <div className="ds-bar-chart">
        <div className="ds-bar-chart__y-axis">
          {yTicks.slice().reverse().map((t) => (
            <span key={t} className="ds-bar-chart__y-label">{t}</span>
          ))}
        </div>
        <div className="ds-bar-chart__body">
          {days.map((day) => (
            <div className="ds-bar-chart__col" key={day.date}>
              <div className="ds-bar-chart__bar-group">
                <div
                  className="ds-bar-chart__bar ds-bar-chart__bar--red"
                  style={{ height: `${(day.failures / yMax) * 100}%` }}
                />
                <div
                  className="ds-bar-chart__bar ds-bar-chart__bar--amber"
                  style={{ height: `${(day.downtime / yMax) * 100}%` }}
                />
              </div>
              <span className="ds-bar-chart__x-label">{day.date}</span>
            </div>
          ))}
        </div>
      </div>
      <div className="ds-chart__legend">
        <span className="ds-chart__legend-item">
          <span className="ds-chart__legend-dot ds-chart__legend-dot--red" />
          Failure count
        </span>
        <span className="ds-chart__legend-item">
          <span className="ds-chart__legend-dot ds-chart__legend-dot--amber" />
          Downtime hours
        </span>
      </div>
    </div>
  );
}

/* --- Inventory Issues Line Chart (SVG) --- */
function InventoryChart() {
  const width = 560;
  const height = 260;
  const pad = { top: 24, right: 20, bottom: 44, left: 40 };
  const cw = width - pad.left - pad.right;
  const ch = height - pad.top - pad.bottom;

  const days = [
    '18 Jul', '19 Jul', '20 Jul', '21 Jul', '22 Jul', '23 Jul', '24 Jul',
    '25 Jul', '26 Jul', '27 Jul', '28 Jul', '29 Jul', '30 Jul', '31 Jul',
  ];
  const stockouts = [8, 12, 10, 14, 18, 16, 12, 14, 20, 22, 18, 16, 20, 24];
  const mismatches = [6, 8, 10, 9, 12, 14, 10, 8, 14, 16, 12, 10, 14, 18];

  const yMax = 24;
  const yTicks = [0, 6, 12, 18, 24];

  const toX = (i: number) => pad.left + (i / (days.length - 1)) * cw;
  const toY = (v: number) => pad.top + ch - (v / yMax) * ch;

  const linePath = (data: number[]) =>
    'M' + data.map((v, i) => `${toX(i)},${toY(v)}`).join(' L');

  const [tooltip, setTooltip] = useState<{ x: number; y: number; idx: number } | null>(null);

  return (
    <div className="ds-card">
      <div className="ds-card__header">
        <h3 className="ds-card__title">Inventory issues — 14 days</h3>
        <p className="ds-card__subtitle">Stockouts cause substitutions; mismatches cause missing-item claims.</p>
      </div>
      <div className="ds-line-chart-wrap">
        <svg
          width="100%"
          height={height}
          viewBox={`0 0 ${width} ${height}`}
          className="ds-line-chart-svg"
          onMouseLeave={() => setTooltip(null)}
        >
          {yTicks.map((tick) => (
            <g key={tick}>
              <line x1={pad.left} y1={toY(tick)} x2={width - pad.right} y2={toY(tick)} stroke="#1a2035" strokeWidth="1" />
              <text x={pad.left - 8} y={toY(tick) + 4} textAnchor="end" className="ds-chart__axis-text">
                {tick}
              </text>
            </g>
          ))}
          {days.filter((_, i) => i % 3 === 0 || i === days.length - 1).map((label, _, arr) => {
            const idx = days.indexOf(label);
            return (
              <text key={label} x={toX(idx)} y={height - 10} textAnchor="middle" className="ds-chart__axis-text">
                {label}
              </text>
            );
          })}
          <path d={linePath(stockouts)} fill="none" stroke="#3b82f6" strokeWidth="2" />
          <path d={linePath(mismatches)} fill="none" stroke="#f59e0b" strokeWidth="2" />
          {days.map((_, i) => (
            <rect
              key={i}
              x={toX(i) - 15}
              y={pad.top}
              width={30}
              height={ch}
              fill="transparent"
              onMouseEnter={(e) => {
                const rect = (e.target as SVGRectElement).getBoundingClientRect();
                setTooltip({ x: rect.left + rect.width / 2, y: rect.top, idx: i });
              }}
            />
          ))}
          {tooltip !== null && (
            <g>
              <line x1={toX(tooltip.idx)} y1={pad.top} x2={toX(tooltip.idx)} y2={pad.top + ch} stroke="#475569" strokeWidth="1" strokeDasharray="3,3" />
              <circle cx={toX(tooltip.idx)} cy={toY(stockouts[tooltip.idx])} r="4" fill="#3b82f6" />
              <circle cx={toX(tooltip.idx)} cy={toY(mismatches[tooltip.idx])} r="4" fill="#f59e0b" />
            </g>
          )}
        </svg>
        {tooltip !== null && (
          <div className="ds-tooltip" style={{ left: toX(tooltip.idx), top: pad.top - 10 }}>
            <div className="ds-tooltip__date">{days[tooltip.idx]}</div>
            <div className="ds-tooltip__row">Stockouts: {stockouts[tooltip.idx]}</div>
            <div className="ds-tooltip__row">Mismatches: {mismatches[tooltip.idx]}</div>
          </div>
        )}
      </div>
      <div className="ds-chart__legend">
        <span className="ds-chart__legend-item">
          <span className="ds-chart__legend-dot ds-chart__legend-dot--blue" />
          Stockouts
        </span>
        <span className="ds-chart__legend-item">
          <span className="ds-chart__legend-dot ds-chart__legend-dot--amber" />
          Stock mismatches
        </span>
      </div>
    </div>
  );
}

