];

function TopCategories() {
  const maxCount = Math.max(...CATEGORIES.map((c) => c.count));

  return (
    <div className="ds-card">
      <div className="ds-card__header">
        <h3 className="ds-card__title">Top complaint categories</h3>
        <p className="ds-card__subtitle">Last 7 days at this store.</p>
      </div>
      <div className="ds-categories">
        {CATEGORIES.map((cat) => (
          <div className="ds-categories__row" key={cat.name}>
            <span className="ds-categories__name">{cat.name}</span>
            <div className="ds-categories__bar-wrap">
              <div
                className="ds-categories__bar"
                style={{ width: `${(cat.count / maxCount) * 100}%` }}
              />
            </div>
            <span className="ds-categories__count">{cat.count}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

/* --- Main Dark Store Dashboard --- */
